INSERT INTO surveys ( owner_id, title, description, anonymous, allow_multiple_responses, max_responses_per_user, version, access_code, report_template_id, settings_json, created_at, updated_at) VALUES (3,'文爱偏好与界限问卷 · 18+','在文字里相遇之前，先让彼此看清对方的底色。这份问卷用于文字亲密创作（文爱）开始前的偏好与界限核对：没有标准答案，只有你的答案。请在安静的时候、慢慢填写。',0,0,1,1,NULL,NULL,'{"theme": {"preset": "black", "background": {"image": "/api/survey/media/-1", "position": "center top", "size": "cover"}, "overlay": {"color": "rgba(8,4,10,0.62)", "blur": 2}, "primaryColor": "#d4576b", "secondaryColor": "#8a2b3f", "card": {"background": "rgba(22,10,16,0.72)", "border": "rgba(212,87,107,0.28)", "radius": 18, "glass": true}, "text": {"heading": "#f7e8ea", "body": "#ecd9dc", "muted": "#b39198"}, "button": {"radius": 24}, "audio": {"url": "/api/survey/media/-2"}, "completion": {"message": "答卷已封好 ✦ 愿你们在文字里尽兴，在现实里安好。"}}}','2026-10-11T00:31:58.633516Z','2026-10-11T00:31:58.633516Z');
