INSERT INTO survey_questions ( survey_id, type, title, description, required, "order", page_id, settings_json, created_at, updated_at) SELECT (SELECT id FROM surveys WHERE title = '文爱偏好与界限问卷 · 18+' AND created_at = '2026-10-11T00:31:58.633516Z' LIMIT 1), json_extract(item.value,'$.type'), json_extract(item.value,'$.title'), json_extract(item.value,'$.description'), CAST(json_extract(item.value,'$.required') AS INTEGER), CAST(json_extract(item.value,'$.order') AS INTEGER), page.id, json_extract(item.value,'$.settingsJson'),'2026-10-11T00:31:58.633516Z','2026-10-11T00:31:58.633516Z' FROM json_each('[{"type": "note", "title": "写给深夜的你", "description": "这不是一份普通的问卷，它更像一封信——写给未来某个深夜，隔着屏幕与你用文字取暖的那个人。\n\n慢慢写，不着急。每一道题都没有标准答案，只有你的答案。", "required": 0, "order": 1, "pageOrder": 0, "settingsJson": null}, {"type": "yes_no", "title": "我已年满 18 周岁，并自愿填写这份问卷。", "description": "本问卷包含成人向内容，仅面向成年人。如果你还未成年，请在这里停下。", "required": 1, "order": 2, "pageOrder": 0, "settingsJson": null}, {"type": "yes_no", "title": "我理解：文爱是完全的虚构创作。", "description": "问卷里的偏好只关乎文字里的世界，不代表现实中的邀请或承诺；任何时候、任何一方都可以叫停。", "required": 1, "order": 3, "pageOrder": 0, "settingsJson": null}, {"type": "single", "title": "你的文爱经验大概是……", "description": null, "required": 1, "order": 4, "pageOrder": 0, "settingsJson": null}]') AS item LEFT JOIN survey_pages page ON page.survey_id = (SELECT id FROM surveys WHERE title = '文爱偏好与界限问卷 · 18+' AND created_at = '2026-10-11T00:31:58.633516Z' LIMIT 1) AND page."order" = CAST(json_extract(item.value,'$.pageOrder') AS INTEGER);
INSERT INTO survey_questions ( survey_id, type, title, description, required, "order", page_id, settings_json, created_at, updated_at) SELECT (SELECT id FROM surveys WHERE title = '文爱偏好与界限问卷 · 18+' AND created_at = '2026-10-11T00:31:58.633516Z' LIMIT 1), json_extract(item.value,'$.type'), json_extract(item.value,'$.title'), json_extract(item.value,'$.description'), CAST(json_extract(item.value,'$.required') AS INTEGER), CAST(json_extract(item.value,'$.order') AS INTEGER), page.id, json_extract(item.value,'$.settingsJson'),'2026-10-11T00:31:58.633516Z','2026-10-11T00:31:58.633516Z' FROM json_each('[{"type": "note", "title": "底色 · 你如何书写", "description": "先让我们认识「写字的你」。\n\n文字是这里唯一的身体：它怎么呼吸、怎么移动、怎么发出声音，全都由你的笔迹决定。", "required": 0, "order": 5, "pageOrder": 1, "settingsJson": null}, {"type": "text", "title": "希望对方在文字里怎么称呼你？", "description": null, "required": 1, "order": 6, "pageOrder": 1, "settingsJson": null}, {"type": "single", "title": "偏好的叙事视角", "description": null, "required": 1, "order": 7, "pageOrder": 1, "settingsJson": null}, {"type": "single", "title": "单条回复的理想篇幅", "description": null, "required": 1, "order": 8, "pageOrder": 1, "settingsJson": null}]') AS item LEFT JOIN survey_pages page ON page.survey_id = (SELECT id FROM surveys WHERE title = '文爱偏好与界限问卷 · 18+' AND created_at = '2026-10-11T00:31:58.633516Z' LIMIT 1) AND page."order" = CAST(json_extract(item.value,'$.pageOrder') AS INTEGER);
