INSERT INTO survey_versions (survey_id, version, snapshot_json, created_by, created_at) VALUES ((SELECT id FROM surveys WHERE title = '文爱偏好与界限问卷 · 18+' AND created_at = '2026-10-11T00:31:58.633516Z' LIMIT 1), (SELECT version FROM surveys WHERE title = '文爱偏好与界限问卷 · 18+' AND created_at = '2026-10-11T00:31:58.633516Z'), '{"schema": {"schema_version": 1, "survey": {"title": "文爱偏好与界限问卷 · 18+", "description": "在文字里相遇之前，先让彼此看清对方的底色。这份问卷用于文字亲密创作（文爱）开始前的偏好与界限核对：没有标准答案，只有你的答案。请在安静的时候、慢慢填写。", "cover": {"id": "m-cover", "type": "photo", "source": "kv", "url": "kv://cover.jpg", "width": 1600, "height": 1000}, "pages": [{"id": "p1", "title": "序 · 写给深夜的你", "order": 1}, {"id": "p2", "title": "一 · 底色", "order": 2}, {"id": "p3", "title": "二 · 幕布", "order": 3}, {"id": "p4", "title": "三 · 尺度", "order": 4}, {"id": "p5", "title": "四 · 界限", "order": 5}, {"id": "p6", "title": "五 · 安全词", "order": 6}, {"id": "p7", "title": "六 · 落笔", "order": 7}], "questions": [{"id": "q-p1-note", "type": "note", "title": "写给深夜的你", "description": "这不是一份普通的问卷，它更像一封信——写给未来某个深夜，隔着屏幕与你用文字取暖的那个人。\n\n慢慢写，不着急。每一道题都没有标准答案，只有你的答案。", "required": false, "order": 1, "page_id": "p1", "options": [], "media": [{"id": "m-p1", "type": "photo", "source": "kv", "url": "kv://p1.jpg", "width": 1600, "height": 1000}]}, {"id": "q-age", "type": "yes_no", "title": "我已年满 18 周岁，并自愿填写这份问卷。", "description": "本问卷包含成人向内容，仅面向成年人。如果你还未成年，请在这里停下。", "required": true, "order": 2, "page_id": "p1", "options": [{"id": "o-yes", "label": "是，我已成年", "value": "yes", "order": 1}, {"id": "o-no", "label": "否", "value": "no", "order": 2}], "media": []}, {"id": "q-fiction", "type": "yes_no", "title": "我理解：文爱是完全的虚构创作。", "description": "问卷里的偏好只关乎文字里的世界，不代表现实中的邀请或承诺；任何时候、任何一方都可以叫停。", "required": true, "order": 3, "page_id": "p1", "options": [{"id": "o-yes", "label": "是，我理解", "value": "yes", "order": 1}, {"id": "o-no", "label": "否", "value": "no", "order": 2}], "media": []}, {"id": "q-exp", "type": "single", "title": "你的文爱经验大概是……", "required": true, "order": 4, "page_id": "p1", "options": [{"id": "o-new", "label": "初次尝试，请多指教", "value": "newbie", "order": 1}, {"id": "o-some", "label": "有一些经验", "value": "some", "order": 2}, {"id": "o-veteran", "label": "老手了，什么场面都见过", "value": "veteran", "order": 3}, {"id": "o-unsure", "label": "还不确定，先来看看", "value": "unsure", "order": 4}], "media": []}, {"id": "q-p2-note", "type": "note", "title": "底色 · 你如何书写", "description": "先让我们认识「写字的你」。\n\n文字是这里唯一的身体：它怎么呼吸、怎么移动、怎么发出声音，全都由你的笔迹决定。", "required": false, "order": 5, "page_id": "p2", "options": [], "media": [{"id": "m-p2", "type": "photo", "source": "kv", "url": "kv://p2.jpg", "width": 1600, "height": 1000}]}, {"id": "q-name", "type": "text", "title": "希望对方在文字里怎么称呼你？", "required": true, "order": 6, "page_id": "p2", "options": [], "media": [], "placeholder": "一个昵称、代号，或一个只在这里使用的名字"}, {"id": "q-pov", "type": "single", "title": "偏好的叙事视角", "required": true, "order": 7, "page_id": "p2", "options": [{"id": "o-first", "label": "第一人称「我」，沉浸感最强", "value": "first", "order": 1}, {"id": "o-second", "label": "第二人称「你」，被书写的感觉", "value": "second", "order": 2}, {"id": "o-third", "label": "第三人称，像看一场电影", "value": "third", "order": 3}, {"id": "o-mixed", "label": "混着来，看感觉", "value": "mixed", "order": 4}], "media": []}, {"id": "q-length", "type": "single", "title": "单条回复的理想篇幅", "required": true, "order": 8, "page_id": "p2", "options": [{"id": "o-short", "label": "一两行，短句快节奏", "value": "short", "order": 1}, {"id": "o-medium", "label": "两三段，有呼吸感", "value": "medium", "order": 2}, {"id": "o-long", "label": "大段长文，细描慢写", "value": "long", "order": 3}, {"id": "o-flex", "label": "不固定，跟着节奏走", "value": "flexible", "order": 4}], "media": []}, {"id": "q-style", "type": "multiple", "title": "你的文风更接近哪几种？（可多选）", "required": true, "order": 9, "page_id": "p2", "options": [{"id": "o-sensory", "label": "细腻的感官描写", "value": "sensory", "order": 1}, {"id": "o-direct", "label": "直白热烈，不绕弯子", "value": "direct", "order": 2}, {"id": "o-hint", "label": "氛围与留白的暗示", "value": "subtle", "order": 3}, {"id": "o-dialogue", "label": "以对话推进", "value": "dialogue", "order": 4}, {"id": "o-inner", "label": "心理与情绪的独白", "value": "inner", "order": 5}, {"id": "o-ornate", "label": "讲究辞藻与笔触", "value": "ornate", "order": 6}, {"id": "o-raw", "label": "粗粝原始，带点野性", "value": "raw", "order": 7}], "media": []}, {"id": "q-pace", "type": "single", "title": "理想的互动节奏", "required": true, "order": 10, "page_id": "p2", "options": [{"id": "o-live", "label": "即时的，像深夜热聊", "value": "live", "order": 1}, {"id": "o-few", "label": "一天几条，细水长流", "value": "few_daily", "order": 2}, {"id": "o-slow", "label": "慢热长线，一天一两条也行", "value": "slow", "order": 3}, {"id": "o-mood", "label": "看状态，随缘", "value": "mood", "order": 4}], "media": []}, {"id": "q-heat", "type": "rating", "title": "文字的情色浓度，你想要几分？", "description": "1 = 几乎全是暗示与留白；5 = 直白、详尽、不加修饰。", "required": true, "order": 11, "page_id": "p2", "options": [{"id": "o-r1", "label": "1", "value": "1", "order": 1}, {"id": "o-r2", "label": "2", "value": "2", "order": 2}, {"id": "o-r3", "label": "3", "value": "3", "order": 3}, {"id": "o-r4", "label": "4", "value": "4", "order": 4}, {"id": "o-r5", "label": "5", "value": "5", "order": 5}], "media": []}, {"id": "q-p3-note", "type": "note", "title": "幕布 · 在哪里、以什么身份相遇", "description": "同一个夜晚，可以发生在很多种地方。\n\n选一选让你心动的布景，再决定你们之间是什么样的关系。", "required": false, "order": 12, "page_id": "p3", "options": [], "media": [{"id": "m-p3", "type": "photo", "source": "kv", "url": "kv://p3.jpg", "width": 1600, "height": 1000}]}, {"id": "q-scene", "type": "multiple", "title": "哪些情境让你心动？（可多选）", "required": true, "order": 13, "page_id": "p3", "options": [{"id": "o-latenight", "label": "深夜私语 · 聊天窗里的即时呼吸", "value": "late_night", "order": 1, "media": [{"id": "m-latenight", "type": "photo", "source": "kv", "url": "kv://scene-latenight.jpg", "width": 800, "height": 600}]}, {"id": "o-hotel", "label": "酒店与旅途 · 陌生的房间与行李箱", "value": "hotel", "order": 2, "media": [{"id": "m-hotel", "type": "photo", "source": "kv", "url": "kv://scene-hotel.jpg", "width": 800, "height": 600}]}, {"id": "o-office", "label": "办公室与制服 · 白天之下的暗流", "value": "office", "order": 3, "media": [{"id": "m-office", "type": "photo", "source": "kv", "url": "kv://scene-office.jpg", "width": 800, "height": 600}]}, {"id": "o-ancient", "label": "古风 · 红帐烛影，衣带轻解", "value": "ancient", "order": 4, "media": [{"id": "m-ancient", "type": "photo", "source": "kv", "url": "kv://scene-ancient.jpg", "width": 800, "height": 600}]}, {"id": "o-fantasy", "label": "幻想 · 精灵、兽耳、异能与月亮", "value": "fantasy", "order": 5, "media": [{"id": "m-fantasy", "type": "photo", "source": "kv", "url": "kv://scene-fantasy.jpg", "width": 800, "height": 600}]}, {"id": "o-city", "label": "都市日常 · 旧识重逢，或陌生人", "value": "city", "order": 6, "media": [{"id": "m-city", "type": "photo", "source": "kv", "url": "kv://scene-city.jpg", "width": 800, "height": 600}]}], "media": []}, {"id": "q-dynamic", "type": "single", "title": "你偏好的关系动态", "required": true, "order": 14, "page_id": "p3", "options": [{"id": "o-equal", "label": "势均力敌，互相撕扯", "value": "equal", "order": 1}, {"id": "o-lead", "label": "一方引导，一方沉溺", "value": "guided", "order": 2}, {"id": "o-push", "label": "欲拒还迎，暧昧拉扯", "value": "push_pull", "order": 3}, {"id": "o-old", "label": "相识已久，水到渠成", "value": "familiar", "order": 4}, {"id": "o-stranger", "label": "初识陌生，危险而新鲜", "value": "strangers", "order": 5}], "media": []}, {"id": "q-mood", "type": "multiple", "title": "想要的氛围基调（可多选）", "required": true, "order": 15, "page_id": "p3", "options": [{"id": "o-slowburn", "label": "慢慢升温的暧昧", "value": "slowburn", "order": 1}, {"id": "o-tender", "label": "温柔缠绵", "value": "tender", "order": 2}, {"id": "o-passionate", "label": "热烈奔放", "value": "passionate", "order": 3}, {"id": "o-shy", "label": "羞涩与紧张", "value": "shy", "order": 4}, {"id": "o-break", "label": "禁欲崩坏后的失控", "value": "collapse", "order": 5}, {"id": "o-danger", "label": "带一点危险的张力", "value": "danger", "order": 6}], "media": []}, {"id": "q-p4-note", "type": "note", "title": "尺度 · 逐项确认你的身体地图", "description": "以下每一项都请凭直觉作答：愿意 / 看情况 / 不愿意。\n\n这里没有「应该」，也没有分数。所有答案只用于创作，不作任何现实解读。", "required": false, "order": 16, "page_id": "p4", "options": [], "media": [{"id": "m-p4", "type": "photo", "source": "kv", "url": "kv://p4.jpg", "width": 1600, "height": 1000}]}, {"id": "q-kiss", "type": "single", "title": "亲吻、拥抱与爱抚", "required": true, "order": 17, "page_id": "p4", "options": [{"id": "o-yes", "label": "愿意", "value": "yes", "order": 1}, {"id": "o-maybe", "label": "看情况", "value": "maybe", "order": 2}, {"id": "o-no", "label": "不愿意", "value": "no", "order": 3}], "media": []}, {"id": "q-whisper", "type": "single", "title": "耳语、情话与挑逗", "required": true, "order": 18, "page_id": "p4", "options": [{"id": "o-yes", "label": "愿意", "value": "yes", "order": 1}, {"id": "o-maybe", "label": "看情况", "value": "maybe", "order": 2}, {"id": "o-no", "label": "不愿意", "value": "no", "order": 3}], "media": []}, {"id": "q-voice", "type": "single", "title": "声音的描写——喘息、气音、拟声与叫床", "required": true, "order": 19, "page_id": "p4", "options": [{"id": "o-yes", "label": "愿意", "value": "yes", "order": 1}, {"id": "o-maybe", "label": "看情况", "value": "maybe", "order": 2}, {"id": "o-no", "label": "不愿意", "value": "no", "order": 3}], "media": []}, {"id": "q-explicit", "type": "single", "title": "直白的性爱场景描写", "required": true, "order": 20, "page_id": "p4", "options": [{"id": "o-yes", "label": "愿意", "value": "yes", "order": 1}, {"id": "o-maybe", "label": "看情况", "value": "maybe", "order": 2}, {"id": "o-no", "label": "不愿意", "value": "no", "order": 3}], "media": []}, {"id": "q-oral", "type": "single", "title": "口（用嘴的爱抚）", "required": true, "order": 21, "page_id": "p4", "options": [{"id": "o-yes", "label": "愿意", "value": "yes", "order": 1}, {"id": "o-maybe", "label": "看情况", "value": "maybe", "order": 2}, {"id": "o-no", "label": "不愿意", "value": "no", "order": 3}], "media": []}, {"id": "q-toys", "type": "single", "title": "穿戴与道具——情趣内衣、玩具", "required": true, "order": 22, "page_id": "p4", "options": [{"id": "o-yes", "label": "愿意", "val