, "required": false, "order": 32, "page_id": "p5", "options": [], "media": []}, {"id": "q-banned-words", "type": "text", "title": "绝对不希望在文字里出现的称呼或词汇", "required": false, "order": 33, "page_id": "p5", "options": [], "media": [], "placeholder": "某个称呼、某种说法，写下来就会永远消失"}, {"id": "q-p6-note", "type": "note", "title": "安全词 · 我们说好的一切", "description": "好的文爱让人放心沉溺，因为知道随时可以被温柔接住。\n\n这一页决定了「出错的时候，怎么办」。", "required": false, "order": 34, "page_id": "p6", "options": [], "media": [{"id": "m-p6", "type": "photo", "source": "kv", "url": "kv://p6.jpg", "width": 1600, "height": 1000}]}, {"id": "q-safeword", "type": "text", "title": "你的安全词", "description": "它一旦出现，一切立刻中止或淡出，不做任何追问。", "required": false, "order": 35, "page_id": "p6", "options": [], "media": [], "placeholder": "例如：红灯、暂停"}, {"id": "q-stop", "type": "single", "title": "如果对方踩到你的界限，你希望对方怎么做？", "required": true, "order": 36, "page_id": "p6", "options": [{"id": "o-halt", "label": "立刻停下，简单确认后等你", "value": "halt", "order": 1}, {"id": "o-fade", "label": "淡出场景，像什么都没发生", "value": "fade", "order": 2}, {"id": "o-signal", "label": "用事先约好的方式提醒", "value": "signal", "order": 3}, {"id": "o-finish", "label": "先把场景收尾，再私下讨论", "value": "finish_then_talk", "order": 4}], "media": []}, {"id": "q-recheck", "type": "yes_no", "title": "需要每次开场都快速重新核对一次界限吗？", "required": true, "order": 37, "page_id": "p6", "options": [{"id": "o-yes", "label": "需要", "value": "yes", "order": 1}, {"id": "o-no", "label": "不需要", "value": "no", "order": 2}], "media": []}, {"id": "q-aftercare", "type": "multiple", "title": "结束之后，你想要的 aftercare 是——", "required": true, "order": 38, "page_id": "p6", "options": [{"id": "o-soothe", "label": "温柔的收尾与安抚", "value": "soothe", "order": 1}, {"id": "o-debrief", "label": "跳出角色，聊聊刚才的感受", "value": "debrief", "order": 2}, {"id": "o-goodnight", "label": "一句「晚安」，然后各自睡去", "value": "goodnight", "order": 3}, {"id": "o-casual", "label": "继续日常闲聊，像无事发生", "value": "casual", "order": 4}, {"id": "o-none", "label": "不需要特别安排，自然结束就好", "value": "none", "order": 5}], "media": []}, {"id": "q-privacy", "type": "single", "title": "关于文字记录与隐私", "required": true, "order": 39, "page_id": "p6", "options": [{"id": "o-burn", "label": "不要保留任何记录，结束即焚", "value": "burn", "order": 1}, {"id": "o-keep", "label": "保留在聊天记录里就好", "value": "keep", "order": 2}, {"id": "o-archive", "label": "可以被整理成只属于我们的小档案", "value": "archive", "order": 3}], "media": []}, {"id": "q-p7-note", "type": "note", "title": "落笔 · 最后，交给你", "description": "前面选的都是「是什么」，接下来可以写「为什么」。\n\n写得含蓄也好、直白也好，对方都会一个字一个字地读。", "required": false, "order": 40, "page_id": "p7", "options": [], "media": [{"id": "m-p7", "type": "photo", "source": "kv", "url": "kv://p7.jpg", "width": 1600, "height": 1000}]}, {"id": "q-fantasy", "type": "long_text", "title": "写一个你幻想过、但从没说出口的场景。", "description": "写得模糊也没有关系。", "required": false, "order": 41, "page_id": "p7", "options": [], "media": []}, {"id": "q-opening", "type": "long_text", "title": "你理想中的开场白是什么样的？", "description": "写一句你希望收到的第一句话。", "required": false, "order": 42, "page_id": "p7", "options": [], "media": []}, {"id": "q-persona", "type": "long_text", "title": "用几句话介绍你在文字里的人格。", "description": "热烈还是克制？主动还是等待？", "required": false, "order": 43, "page_id": "p7", "options": [], "media": []}, {"id": "q-closing-note", "type": "note", "title": "信已封好", "description": "谢谢你如此坦诚。把这份答卷交给对方之前，请记得三件事：\n\n偏好可以随时改变；界限永远优先；以及，屏幕对面的人和你一样，值得被温柔对待。✦", "required": false, "order": 44, "page_id": "p7", "options": [], "media": [{"id": "m-close", "type": "photo", "source": "kv", "url": "kv://closing.jpg", "width": 1600, "height": 1000}]}], "settings": {"anonymous": false, "allow_multiple": false, "max_responses": 1, "shuffle_questions": false, "shuffle_options": false, "show_progress": true, "allow_back": true, "allow_resume": true, "theme": {"preset": "black", "background": {"image": "/api/survey/media/-1", "position": "center top", "size": "cover"}, "overlay": {"color": "rgba(8,4,10,0.62)", "blur": 2}, "primaryColor": "#d4576b", "secondaryColor": "#8a2b3f", "card": {